local __LOADERS = {}
-- Forward declaration: libraries call require_lib at load time.
local require_lib

__LOADERS["catalog"] = function(...)
-- =====================================================================
-- Lib: catalog/pagination helpers for plugin catalogs: hasNextPage,
--      nextIndex/pageUrl (dominant "?page=N" scheme), urlEncode.
-- Loaded via require_lib("catalog"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.1"

local M = {}

-- =====================================================================
-- Pagination
-- =====================================================================

-- "Has next page" for the dominant scheme where a page is considered
-- non-final as long as it returned any item (39 inline copies of
-- `#items > 0`, plus 7 local hasNextPage helpers with the same body).
-- Plugins that know their total page count keep their own comparison.
function M.hasNextPage(items)
    return type(items) == "table" and #items > 0
end

-- Catalog index is 0-based; pages on the wire are 1-based — the
-- dominant `local page = index + 1` from 74 plugins.
function M.nextIndex(index)
    return (index or 0) + 1
end

-- Build a page URL from a template with "{n}" where the 1-based page
-- number goes. Matches the dominant string-concat schemes:
--   ".../catalog?page={n}"        (guide, most sites)
--   "...&pg={n}"                  (en/scribblehub.lua:33)
--   "...&bpage={n}"               (ru/bookhamster.lua:85)
-- Sites with conditional page params or API cursors keep their own code.
function M.pageUrl(template, index)
    return (template:gsub("{n}", tostring(M.nextIndex(index))))
end

-- =====================================================================
-- Query encoding
-- =====================================================================

-- Pure-Lua mirror of the engine global url_encode (Java
-- URLEncoder.encode(s, "UTF-8"): application/x-www-form-urlencoded —
-- space -> "+", unreserved A-Za-z0-9 . - * _ kept, everything else
-- "%XX" uppercase over UTF-8 bytes, "\n" normalized to "\r\n" first).
-- The 73 plugin call sites use the engine global directly; this copy
-- exists for shared libs and parity tests outside the engine.
-- Byte-wise whitelist: LuaJ's %w matches Latin-1 letters (0xC0-0xFF), so a
-- UTF-8 byte like 0xE3 would stay raw and corrupt the query (CJK/Cyrillic
-- search returned 0). Java URLEncoder keeps only A-Z a-z 0-9 . - * _.
local function unreserved(b)
    return (b >= 48 and b <= 57)
        or (b >= 65 and b <= 90)
        or (b >= 97 and b <= 122)
        or b == 45 or b == 46 or b == 42 or b == 95
end

function M.urlEncode(s)
    if type(s) ~= "string" then return s end
    s = s:gsub("\n", "\r\n")
    return (s:gsub(".", function(c)
        local b = string.byte(c)
        if b == 32 then return "+" end
        if unreserved(b) then return c end
        return string.format("%%%02X", b)
    end))
end

return M
end

__LOADERS["content"] = function(...)
-- =====================================================================
-- Lib: chapter-text cleanup shared by the novel extractors.
-- Loaded via require_lib("content"). No dependencies on other libs.
--
-- Engine API used inside the functions only: string_normalize,
-- regex_replace, string_trim (all guarded, so the module still loads
-- outside the app).
-- =====================================================================
local version = "1.0.0"

local M = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

local function trim(s)
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

-- Chapter-heading prefix that gets stripped when it duplicates the
-- chapter title the engine already shows (guide:823). Language picks the
-- word for the ordinal; unknown/missing lang falls back to the dominant
-- ru/en cluster (Глава N | Chapter N).
local HEAD_BY_LANG = {
    ru = "(Глава\\s+\\d+|Chapter\\s+\\d+)",
    en = "(Chapter\\s+\\d+)",
    zh = "(第[\\d一二三四五六七八九十百]+[章节卷回部集篇]|Chapter\\s+\\d+)",
    ja = "(第\\s*\\d+話|Chapter\\s+\\d+)",
    id = "(Bab\\s+\\d+|Chapter\\s+\\d+)",
}

-- Credit lines: the English set is in every copy that has a credits
-- step at all; the per-language set is the union of the ru (ru/bookhamster,
-- ru/ifreedom, ru/jaomix), zh (zh/twkan, zh/sto9) and id (id/indowebnovel)
-- variants. Both are applied for the chosen language.
local CREDITS_EN =
    "(?im)^\\s*(Translator|Editor|Proofreader|Read\\s+(at|on|latest))[:\\s][^\\n\\r]{0,70}(\\r?\\n|$)"

local CREDITS_BY_LANG = {
    ru = "(?im)^\\s*(Перевод|Переводчик|Редакция|Редактор|Аннотация|Сайт|Источник|Студия)[:\\s][^\\n\\r]{0,70}(\\r?\\n|$)",
    zh = "(?im)^\\s*(翻译|譯者|译者|編輯|编辑|校對|校对|更新|閱讀|阅读|最新閱讀|最新阅读)[:\\s：][^\\n\\r]{0,70}(\\r?\\n|$)",
    id = "(?im)^\\s*(Penerjemah|Editor|Proofreader|Baca\\s+(di|novel|lanjutan)|Sumber|Donasi|Trakteer)[:\\s][^\\n\\r]{0,70}(\\r?\\n|$)",
}

-- Escape regex metacharacters of a literal chapter title or domain
-- (Java/Kotlin regex syntax: backslash-escape, not %-escape).
local function escapeLiteral(s)
    return (s:gsub("[%.%+%-%*%?%[%]%(%){}%$%^%|%%]", "\\%1"))
end

-- applyStandardContentTransforms (guide:812) as a shared function.
--   opts.domain      — baseUrl (or a bare host): lines mentioning it are dropped;
--   opts.chapterTitle — literal title to strip instead of the "Глава/Chapter N"
--                      prefix (duplicates the title field of the chapter);
--   opts.lang        — "ru" (default) / "en" / "zh" / "ja" / "id": picks the
--                      chapter-heading word and the extra credit lines.
-- Returns "" for an empty input, as every copy does.
function M.standardTransforms(text, opts)
    if not text or text == "" then return "" end
    opts = opts or {}
    local lang = opts.lang or "ru"

    if type(string_normalize) == "function" then
        text = string_normalize(text)
    end

    if type(regex_replace) ~= "function" then
        logErr("meta/content: regex_replace unavailable, transforms skipped")
        return trim(text)
    end

    -- 1. lines linking back to the source site (watermarks, "read more")
    local domain = opts.domain
    if type(domain) == "string" and domain ~= "" then
        domain = domain:gsub("https?://", ""):gsub("^www%.", ""):gsub("/$", "")
        if domain ~= "" then
            text = regex_replace(text, "(?i)" .. escapeLiteral(domain) .. ".*?\\n", "")
        end
    end

    -- 2. leading chapter heading, duplicated in the title field
    local head = opts.chapterTitle
        and ("(" .. escapeLiteral(opts.chapterTitle) .. ")")
        or HEAD_BY_LANG[lang] or HEAD_BY_LANG.ru
    text = regex_replace(text, "(?i)\\A[\\s\\p{Z}\\uFEFF]*(" .. head .. "[^\\n\\r]*[\\n\\r\\s]*)+", "")

    -- 3. translator / editor / "read at" credit lines
    text = regex_replace(text, CREDITS_EN, "")
    local credits = CREDITS_BY_LANG[lang]
    if credits then text = regex_replace(text, credits, "") end

    -- 4. trim (string_trim collapses nothing but the edges, as in the copies)
    if type(string_trim) == "function" then
        return string_trim(text)
    end
    return trim(text)
end

return M
end

__LOADERS["fetch"] = function(...)
-- =====================================================================
-- Lib: session-cached page fetch. The engine calls getBookTitle /
-- getBookCoverImageUrl / getBookDescription / getBookGenres /
-- getBookStatus / getBookLastUpdate in parallel, each doing its own
-- http_get(bookUrl) — this module keeps one request per URL.
-- Loaded via require_lib("fetch"). No dependencies on other libs.
--
-- Same contract as the inline fetchPage copies (guide:643):
--   * cache lives for the session only, never for getChapterListHash —
--     that one must always use a direct http_get;
--   * only successful responses are cached, a failed call returns nil
--     and the next call retries;
--   * the cache key is the URL. A non-empty `config` that changes the
--     response body (headers, charset, ...) becomes part of the key, so
--     two configs never share a body.
-- =====================================================================
local version = "1.0.0"

local M = {}

local cache = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

-- Order-independent encoding of a config table, so {a=1,b=2} and {b=2,a=1}
-- share one cache entry. Cycles are not possible here: http_get configs are
-- plain string/number/bool values and one level of headers table.
local function encode(value)
    local t = type(value)
    if t == "table" then
        local keys = {}
        for k in pairs(value) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
        local parts = {}
        for _, k in ipairs(keys) do
            parts[#parts + 1] = tostring(k) .. "=" .. encode(value[k])
        end
        return "{" .. table.concat(parts, ";") .. "}"
    end
    return tostring(value)
end

local function keyOf(url, config)
    if type(config) ~= "table" then return url end
    local keys = {}
    for k in pairs(config) do keys[#keys + 1] = k end
    if #keys == 0 then return url end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    local parts = {}
    for _, k in ipairs(keys) do
        parts[#parts + 1] = tostring(k) .. "=" .. encode(config[k])
    end
    return url .. "\0" .. table.concat(parts, ";")
end

-- GET `url` (optional http_get `config`) -> response body or nil.
-- ponytail: no TTL — the plugin session is short-lived and every copy in
-- the repo caches for the whole session (only mtl/wtrlab.lua adds a TTL);
-- add one when a caller actually needs staleness control.
function M.page(url, config)
    if type(url) ~= "string" or url == "" then return nil end
    local key = keyOf(url, config)
    local cached = cache[key]
    if cached ~= nil then return cached end
    local r = http_get(url, config)
    if type(r) ~= "table" or not r.success then
        logErr("fetch: GET failed (HTTP " .. tostring(r and r.code) .. ") " .. url)
        return nil
    end
    cache[key] = r.body
    return r.body
end

-- Drop the whole session cache, or every entry of one URL when given
-- (all config variants of that URL).
function M.clear(url)
    if url == nil then
        cache = {}
        return
    end
    local prefix = url .. "\0"
    for key in pairs(cache) do
        if key == url or key:sub(1, #prefix) == prefix then cache[key] = nil end
    end
end

return M
end

__LOADERS["meta"] = function(...)
-- =====================================================================
-- Lib: book metadata normalization (rating, update date, status,
--      genre list) shared by the novel extractors.
-- Loaded via require_lib("meta"). No dependencies on other libs.
--
-- Nothing here maps or invents values: an input the site did not really
-- send comes back as nil (plus a log line) so the app shows nothing
-- instead of a made-up number.
-- =====================================================================
local version = "1.0.0"

local M = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

local function trim(s)
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

-- =====================================================================
-- Rating
-- =====================================================================

-- First number in a rating string -> number in the site's own scale
-- (the app rescales), nil when there is none or it is out of range.
-- Covers the formats used by the getBookRating copies: "4.6" (bare
-- number / data-rating attribute), "8/10", "Rating: 7.5/10", "Rating: 9",
-- "Rank: 3" and the comma decimal separator ("4,6" = 4.6).
function M.rating(str)
    if type(str) ~= "string" then return nil end
    local n = str:match("(%d+[%.,]%d+)") or str:match("(%d+)")
    if not n then
        logErr("meta.rating: no number in " .. str:sub(1, 60))
        return nil
    end
    local v = tonumber((n:gsub(",", ".")))
    if not v or v < 0 or v > 10 then
        logErr("meta.rating: out of 0..10 range: " .. str:sub(1, 60))
        return nil
    end
    return v
end

-- =====================================================================
-- Last update date
-- =====================================================================

-- Relative "N <unit> ago" — EN from the normalizeUpdateDate copies
-- (en/novelphoenix.lua:305, en/freewebnovel.lua, en/lightnovelpub.lua,
-- en/wuxiabox.lua, mtl/sonicmtl.lua), RU from ru/ifreedom.lua:120 and
-- ru/jaomix.lua (which matches the unit as a substring, so plurals and
-- the odd abbreviation keep working). Months/years are approximate
-- (30/365 days), as in those copies.
local REL_EN = {
    second = 1, seconds = 1,
    minute = 60, minutes = 60,
    hour = 3600, hours = 3600,
    day = 86400, days = 86400,
    week = 604800, weeks = 604800,
    month = 2592000, months = 2592000,
    year = 31536000, years = 31536000,
}

local REL_RU = {
    { "секунд", 1 }, { "сек", 1 }, { "минут", 60 }, { "мин", 60 },
    { "час", 3600 }, { "ч", 3600 }, { "дн", 86400 },
    { "недел", 604800 }, { "нед", 604800 },
    { "месяц", 2592000 }, { "мес", 2592000 },
    { "год", 31536000 }, { "лет", 31536000 }, { "г", 31536000 },
}

local function relativeDate(str)
    local n, unit = str:match("(%d+)%s+([%a]+)%s+ago")
    if n then
        local secs = REL_EN[unit]
        if not secs then return nil end
        return os.date("%Y-%m-%d", os.time() - tonumber(n) * secs)
    end
    local num, word = str:match("(%d+)%s*([^%d%s]+)%s+назад")
    if not num then return nil end
    for _, pair in ipairs(REL_RU) do
        if word:find(pair[1], 1, true) then
            return os.date("%Y-%m-%d", os.time() - tonumber(num) * pair[2])
        end
    end
    return nil
end

-- Any date-ish string -> "YYYY-MM-DD" or nil (guide:277). Recognized:
-- ISO 8601 anywhere in the string ("2026-08-18T23:00:15.751Z") and the
-- relative forms above ("Updated 3 days ago", "3 дня назад"). Anything
-- else (month names, DD.MM.YY, site-specific wording) is deliberately
-- not guessed — pass the site's own format from the plugin.
function M.normalizeDate(str)
    if type(str) ~= "string" or str == "" then return nil end
    local y, m, d = str:match("(%d%d%d%d)%-(%d%d)%-(%d%d)")
    if y then return y .. "-" .. m .. "-" .. d end
    local rel = relativeDate(str)
    if rel then return rel end
    logErr("meta.normalizeDate: unrecognized " .. str:sub(1, 60))
    return nil
end

-- =====================================================================
-- Status
-- =====================================================================

-- Status text is shown by the app as-is (guide:264) — no mapping, no
-- case folding by default: plugins return the site's own string. Pass
-- { lower = true } only when the plugin really wants a lowercase label
-- (en/novelfire.lua is the only copy that lowercases).
function M.status(str, opts)
    if type(str) ~= "string" then return nil end
    local s = trim((str:gsub("%s+", " ")))
    if s == "" then return nil end
    if opts and opts.lower then
        if type(string_lower) == "function" then
            s = string_lower(s)
        else
            s = s:lower()
        end
    end
    return s
end

-- =====================================================================
-- Genres
-- =====================================================================

-- Collects genre names out of the elements returned by html_select (or
-- plain strings) — the shared inner loop of the getBookGenres copies
-- (e.g. ar/mangalik.lua:125, ru/allhentai.lua:179): trim/clean the label,
-- drop empties, drop duplicates, keep the site order. The selector and
-- the data source stay in the plugin.
function M.collectGenres(anchors, opts)
    local out, seen = {}, {}
    if type(anchors) ~= "table" then return out end
    for _, el in ipairs(anchors) do
        local raw
        if type(el) == "string" then
            raw = el
        elseif type(el) == "table" then
            raw = el.text
        end
        if type(raw) == "string" and raw ~= "" then
            local name
            if opts and opts.clean and type(string_clean) == "function" then
                name = string_clean(raw)
            elseif type(string_trim) == "function" then
                name = string_trim(raw)
            else
                name = trim(raw)
            end
            if name ~= "" and not seen[name] then
                seen[name] = true
                out[#out + 1] = name
            end
        end
    end
    return out
end

return M
end

__LOADERS["text"] = function(...)
-- =====================================================================
-- Lib: text rotations (rot13, rot18).
-- No XOR here on purpose: the xor "duplicates" found in three plugins are
-- internals of hmac-sha256 / AES-GCM and disappear with the Kotlin APIs,
-- the only standalone str-xor (en/hianimes.lua) stays inline in the plugin.
-- Loaded via require_lib("text"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.0"

local M = {}

-- ROT13 over Latin letters. Bodies of the three copies were equivalent:
-- libs/voe.lua:15, ar/anime4up.lua:383, en/novelhi.lua:33 (the guard for
-- nil/empty comes from novelhi).
function M.rot13(s)
    if not s or s == "" then return "" end
    return (s:gsub("[%a]", function(c)
        local b = c:byte()
        local base = (b < 97) and 65 or 97
        return string.char(base + ((b - base + 13) % 26))
    end))
end

-- Kodik rotation: +18 over letters only, digits untouched — this is NOT
-- the classic ROT13+ROT5 pair, digits must survive as-is or the base64
-- after decoding breaks (sole copy: ru/yummyanime.lua:511 kodikDecode).
function M.rot18(s)
    if not s or s == "" then return "" end
    local t = {}
    for i = 1, #s do
        local b = s:byte(i)
        if b >= 65 and b <= 90 then
            b = b + 18
            if b > 90 then b = b - 26 end
        elseif b >= 97 and b <= 122 then
            b = b + 18
            if b > 122 then b = b - 26 end
        end
        t[#t + 1] = string.char(b)
    end
    return table.concat(t)
end

return M
end

__LOADERS["urls"] = function(...)
-- =====================================================================
-- Lib: shared URL helpers (origin, unescapeSlashes, hostOf, resolve,
--      absUrl, driveDirectUrl) for videohost and novel extractors.
-- Loaded via require_lib("urls"). No dependencies on other libs.
-- =====================================================================
local version = "1.2.0"

local M = {}

-- =====================================================================
-- URL helpers
-- =====================================================================

function M.origin(url)
    local scheme, host = url:match("^(https?)://([^/?#]+)")
    if not scheme then return nil end
    return scheme .. "://" .. host .. "/"
end

function M.unescapeSlashes(s)
    local r = s:gsub("\\/", "/")
    r = r:gsub("\\u0026", "&")
    return r
end

function M.hostOf(url)
    return ((url or ""):match("^https?://([^/?#:]+)") or ""):lower()
end

-- Relative / protocol-relative URL -> absolute (relative to the embed).
function M.resolve(u, embedUrl)
    u = M.unescapeSlashes(u)
    if u:sub(1, 2) == "//" then return "https:" .. u end
    if u:find("^https?://") then return u end
    local o = M.origin(embedUrl or "")
    if o then
        o = o:gsub("/$", "")
        return o .. (u:sub(1, 1) == "/" and u or ("/" .. u))
    end
    return u
end

-- RFC 3986 merge, mirroring java.net.URI(base):resolve(href) — the exact
-- semantics of the engine global url_resolve (plugin-tester-jvm
-- LuaEngineCli.kt:355). Used only when that global is unavailable
-- (offline tests); in the app the global always wins.
local function removeDotSegments(p)
    local leading = p:sub(1, 1) == "/"
    local segs = {}
    for seg in p:gmatch("[^/]+") do
        if seg == ".." then
            if #segs > 0 and segs[#segs] ~= ".." then
                segs[#segs] = nil
            elseif not leading then
                segs[#segs + 1] = seg
            end
        elseif seg ~= "." then
            segs[#segs + 1] = seg
        end
    end
    local out = table.concat(segs, "/")
    if leading then out = "/" .. out end
    if p:sub(-1) == "/" and out:sub(-1) ~= "/" then out = out .. "/" end
    return out
end

local function splitRef(u)
    local path, query, fragment = u, "", ""
    local hash = path:find("#", 1, true)
    if hash then fragment = path:sub(hash + 1) path = path:sub(1, hash - 1) end
    local qm = path:find("?", 1, true)
    if qm then query = path:sub(qm + 1) path = path:sub(1, qm - 1) end
    return path, query, fragment
end

local function resolveRef(base, ref)
    if type(base) ~= "string" or type(ref) ~= "string" then return ref end
    if ref:match("^%a[%w+.-]*:") then return ref end
    local scheme, authority, rest = base:match("^(%a[%w+.-]*)://([^/?#]*)(.*)$")
    if not scheme then return ref end
    if ref:sub(1, 2) == "//" then return scheme .. "://" .. ref:sub(3) end
    local rPath, rQuery, rFrag = splitRef(ref)
    local bPath, bQuery = splitRef(rest)
    local path, query
    if rPath == "" then
        path = bPath
        query = (rQuery ~= "") and rQuery or bQuery
    elseif rPath:sub(1, 1) == "/" then
        path = rPath
        query = rQuery
    else
        path = (bPath:match("^.*/") or "/") .. rPath
        query = rQuery
    end
    local out = scheme .. "://" .. authority .. removeDotSegments(path)
    if query ~= "" then out = out .. "?" .. query end
    if rFrag ~= "" then out = out .. "#" .. rFrag end
    return out
end

-- href found in a page -> absolute URL, relative to `base` (usually baseUrl).
-- Union of the two inline variants: the dominant url_resolve one (guide:1763,
-- 36 byte-identical copies, e.g. ru/ranobehub.lua:11) and the manual sub/find
-- one (es/latanime.lua:94, en/hianimes.lua:50, id/anichin.lua:70). They agree
-- on absolute / protocol-relative / root-relative hrefs; for a bare relative
-- href the canonical url_resolve merge (RFC 3986) is used, the manual copies
-- joined it as baseDir .. "/" .. href — plugins relying on that join must be
-- checked during migration. Empty or non-string href -> "" (guide template).
function M.absUrl(base, href)
    if type(href) ~= "string" or href == "" then return "" end
    if href:sub(1, 4) == "http" then return href end
    if href:sub(1, 2) == "//" then return "https:" .. href end
    if type(url_resolve) == "function" then return url_resolve(base, href) end
    return resolveRef(base, href)
end

-- Google Drive file page -> direct usercontent download URL, no network:
-- the file id lives in the link itself (checked live 2026-10-03, usercontent
-- with confirm=t answers 206 without a single header).
-- Merged from the four inline copies: ar/anime4up.lua:813, ar/witanime.lua:1423,
-- ar/animephoenix.lua:698, es/latanime.lua:280 — all equivalent; the union keeps
-- the nil-safe host match (anime4up dereferenced match() without `or ""`).
-- ponytail: no playback-API fallback for "download disabled" (403 + UA binding) —
-- add it when locked links actually show up on the sites.
function M.driveDirectUrl(link)
    if type(link) ~= "string" then return nil end
    local host = (link:match("^https?://([^/]+)") or ""):lower()
    host = host:gsub("^www%.", "")
    if host ~= "drive.google.com" and host ~= "drive.usercontent.google.com" then
        return nil
    end
    local id = link:match("/file/d/([%w_-]+)") or link:match("[?&]id=([%w_-]+)")
    if not id then return nil end
    local u = "https://drive.usercontent.google.com/download?id=" .. id
        .. "&export=download&confirm=t"
    local rk = link:match("[?&]resourcekey=([%w_-]+)")
    if rk then u = u .. "&resourcekey=" .. rk end
    return u
end

return M
end

require_lib = function(id)
    local cached = rawget(__LIBS, id)
    if cached ~= nil then return cached end
    local loader = rawget(__LOADERS, id)
    if loader == nil then error("bundle_libs: unknown library id: " .. tostring(id), 2) end
    local value = loader()
    __LIBS[id] = value
    return value
end
-- END BUNDLED LIBRARIES (tools/bundle_libs.py)
id       = "mvlempyr.com"
name     = "MVLEMPYR"
version  = "1.0.7"
baseUrl  = "https://www.mvlempyr.io"
language = {"en", "es", "fr"}
icon     = "https://raw.githubusercontent.com/Stlucifer15t/external-sources/refs/heads/main/icons/mvlempyr.webp"

local chapSite = "https://chap.heliosarchive.online/"

local _allNovels = nil

-- ── Helpers ─────────────────────────────────────────────────────────────────

-- Old builds ship no require_lib: keep the plugin loadable (a top-level error
-- would drop it from the source list) and fail with a visible message on the
-- first call instead. Shared libs load lazily and are cached per session.
local _libs
local function LIB(id)
    if type(require_lib) ~= "function" then
        show_error("Requires Dreamora update", "This plugin needs the shared libraries")
        error("Requires Dreamora update (require_lib)", 0)
    end
    if not _libs then _libs = {} end
    if not _libs[id] then _libs[id] = require_lib(id) end
    return _libs[id]
end

local function absUrl(href)
    return LIB("urls").absUrl(baseUrl, href)
end

-- Session-cached page fetch (shared fetch lib, same contract as before).
local function fetchPage(url)
    return LIB("fetch").page(url)
end

local function checkCaptcha(body)
    local titleEl = html_select_first(body, "title")
    if titleEl then
        local title = string_trim(titleEl.text)
        if title == "Attention Required! | Cloudflare" or title == "Just a moment..." then
            return true
        end
    end
    return false
end

-- Chapter-text cleanup from the shared content lib (this site's copy only
-- stripped the translator credits — no site-domain lines on the chap host).
local function applyStandardContentTransforms(text)
    return LIB("content").standardTransforms(text, { lang = "en" })
end

local function mulmod(a, b, m)
    local result = 0
    a = a % m
    b = b % m
    while b > 0 do
        if b % 2 == 1 then
            result = (result + a) % m
        end
        a = (a * 2) % m
        b = math.floor(b / 2)
    end
    return result
end

local function convertNovelId(e)
    local MOD = 1999999997
    local result = 1
    local base = 7 % MOD
    local exp = math.floor(e)
    while exp > 0 do
        if exp % 2 == 1 then
            result = mulmod(result, base, MOD)
        end
        base = mulmod(base, base, MOD)
        exp = math.floor(exp / 2)
    end
    return result
end

local function paginate(data, index)
    local startIdx = index * 20
    local result = {}
    for i = startIdx + 1, math.min(startIdx + 20, #data) do
        table.insert(result, data[i])
    end
    return result
end

local function parseDateTime(dateStr)
    if not dateStr or dateStr == "" then return 0 end
    local y, m, d, h, min, s = dateStr:match("(%d+)%-(%d+)%-(%d+)T(%d+):(%d+):(%d+)")
    if not y then return 0 end
    local t = os.time({
        year = tonumber(y), month = tonumber(m), day = tonumber(d),
        hour = tonumber(h), min = tonumber(min), sec = tonumber(s)
    })
    return (t or 0) * 1000
end

local function toSlug(s)
    if not s then return "" end
    s = tostring(s):lower()
    s = s:gsub("[^%w]+", "-")
    s = s:gsub("^%-+", ""):gsub("%-+$", "")
    return s
end

local function normalizeList(list)
    local result = {}
    if type(list) ~= "table" then return result end
    for _, v in ipairs(list) do
        if type(v) == "table" then
            -- на случай если API вернёт объекты { slug = "...", name = "..." }
            v = v.slug or v.name or v.value
        end
        local slug = toSlug(v)
        if slug ~= "" then table.insert(result, slug) end
    end
    return result
end

local function novelToItem(novel)
    local item = {
        title = novel.name,
        url   = baseUrl .. "/" .. novel.path,
        cover = novel.cover
    }
    -- Рейтинг из поля average-review API: карточки каталога/поиска на сайте
    -- рендерятся клиентом из этого же поля (см. шаблон "${e["average-review"].toFixed(1)}"
    -- на странице книги), поэтому ключ заполняется и в каталоге, и в поиске.
    -- Голое число по шкале 0-5; при отсутствии отзывов (0) ключ не указываем.
    if (novel.avgReview or 0) > 0 then
        item.rating = tostring(novel.avgReview)
    end
    return item
end

-- ── Load all novels from WP REST API ────────────────────────────────────────

-- ── Persistent local cache for the full novel list ──────────────────────────
-- Пока не подтверждено, что API поддерживает серверную фильтрацию/поиск,
-- жанры/теги фильтруются на клиенте, а значит без полного списка не обойтись.
-- Кэшируем его локально на срок CACHE_TTL, чтобы не тянуть и не парсить
-- заново весь каталог при каждом холодном старте скрипта.
local CACHE_KEY        = "mvl_novels_cache_v2"
local CACHE_TS_KEY     = "mvl_novels_cache_v2_ts"
local CACHE_TTL        = 6 * 60 * 60          -- 6 часов
local CACHE_MAX_BYTES  = 4000000              -- ~4MB — с запасом под каталоги 10-15k+ новелл;
                                               -- при dict-кодировании и ~6000 новелл выходило ~0.8MB

-- Жанры/теги очень сильно повторяются между новеллами (~35 жанров, ~850 тегов на
-- весь каталог), поэтому вместо того чтобы хранить строку в каждой новелле, храним
-- один общий словарь слагов + индексы в него. cover/path тоже избыточны — cover
-- всегда "https://assets.mvlempyr.app/images/600/" .. novelCode .. ".webp", а path
-- всегда "novel/" .. slug, так что храним только novelCode/slug и восстанавливаем
-- остальное при чтении.

local function loadCachedNovels()
    local tsRaw = get_preference(CACHE_TS_KEY)
    local ts = tonumber(tsRaw)
    if not ts then return nil end
    if os.time() - ts > CACHE_TTL then return nil end

    local raw = get_preference(CACHE_KEY)
    if not raw or raw == "" then return nil end

    local payload = json_parse(raw)
    if type(payload) ~= "table" or type(payload.dict) ~= "table" or type(payload.novels) ~= "table" then
        return nil
    end
    if #payload.novels == 0 then return nil end

    local dict = payload.dict
    local novels = {}
    for _, n in ipairs(payload.novels) do
        local genres = {}
        for _, idx in ipairs(n.g or {}) do
            local s = dict[idx]
            if s then table.insert(genres, s) end
        end
        local tags = {}
        for _, idx in ipairs(n.t or {}) do
            local s = dict[idx]
            if s then table.insert(tags, s) end
        end
        table.insert(novels, {
            name         = n.name or "",
            path         = "novel/" .. (n.slug or ""),
            cover        = "https://assets.mvlempyr.app/images/600/" .. (n.code or "") .. ".webp",
            avgReview    = n.r or 0,
            reviewCount  = n.rc or 0,
            chapterCount = n.cc or 0,
            created      = n.cr or 0,
            genres       = genres,
            tags         = tags,
        })
    end
    return novels
end

local function saveCachedNovels(novels)
    local dict = {}
    local dictIndex = {}
    local function idxFor(slug)
        local idx = dictIndex[slug]
        if not idx then
            table.insert(dict, slug)
            idx = #dict
            dictIndex[slug] = idx
        end
        return idx
    end

    local compact = {}
    for _, n in ipairs(novels) do
        local g = {}
        for _, s in ipairs(n.genres) do table.insert(g, idxFor(s)) end
        local t = {}
        for _, s in ipairs(n.tags) do table.insert(t, idxFor(s)) end
        table.insert(compact, {
            name = n.name,
            slug = (n.path or ""):gsub("^novel/", ""),
            code = (n.cover or ""):match("(%d+)%.webp$") or "",
            r    = n.avgReview,
            rc   = n.reviewCount,
            cc   = n.chapterCount,
            cr   = n.created,
            g    = g,
            t    = t,
        })
    end

    local raw = json_stringify({ dict = dict, novels = compact })
    if not raw then return end
    if #raw > CACHE_MAX_BYTES then
        log_info("mvlempyr: skip caching novel list, too large (" .. #raw .. " bytes)")
        return
    end
    set_preference(CACHE_KEY, raw)
    set_preference(CACHE_TS_KEY, tostring(os.time()))
end

local function loadAll()
    local url = chapSite .. "wp-json/wp/v2/mvl-novels?per_page=15000"
    local r = http_get(url)
    if not r.success then
        log_error("mvlempyr: failed to load novel list code=" .. tostring(r.code))
        return {}
    end
    local data = json_parse(r.body)
    if not data or type(data) ~= "table" then return {} end

    local novels = {}
    for _, novel in ipairs(data) do
        local novelCode = novel["novel-code"] or ""
        local genres = novel.genre
        if type(genres) == "string" then
            local arr = {}
            for g in genres:gmatch("[^,]+") do table.insert(arr, string_trim(g)) end
            genres = arr
        end
        local tags = novel.tags
        if type(tags) == "string" then
            local arr = {}
            for t in tags:gmatch("[^,]+") do table.insert(arr, string_trim(t)) end
            tags = arr
        end
        table.insert(novels, {
            name         = novel.name or "",
            path         = "novel/" .. (novel.slug or ""),
            cover        = "https://assets.mvlempyr.app/images/600/" .. novelCode .. ".webp",
            avgReview    = tonumber(novel["average-review"]) or 0,
            reviewCount  = tonumber(novel["total-reviews"]) or 0,
            chapterCount = tonumber(novel["total-chapters"]) or 0,
            created      = parseDateTime(novel["createdOn"] or ""),
            genres       = normalizeList(genres),
            tags         = normalizeList(tags),
        })
    end
    return novels
end

local function getAllNovels()
    if _allNovels then return _allNovels end

    local cached = loadCachedNovels()
    if cached then
        _allNovels = cached
        return _allNovels
    end

    _allNovels = loadAll()
    if _allNovels and #_allNovels > 0 then
        saveCachedNovels(_allNovels)
    end
    return _allNovels
end

local function getNovelIdFromBody(body)
    local el = html_select_first(body, "#novel-code")
    if not el then return nil end
    local code = string_trim(el.text or "")
    if code == "" then return nil end
    local num = tonumber(code)
    if not num then return nil end
    return convertNovelId(num)
end

-- ── Filter and sort logic ───────────────────────────────────────────────────

local function filterAndSort(novels, filters)
    local filtered = {}
    for _, novel in ipairs(novels) do
        local include = true

        if filters then
            local genresExc = normalizeList(filters["genres_excluded"])
            for _, g in ipairs(genresExc) do
                for _, ng in ipairs(novel.genres) do
                    if ng == g then include = false; break end
                end
                if not include then break end
            end

            if include then
                local genresInc = normalizeList(filters["genres_included"])
                for _, g in ipairs(genresInc) do
                    local found = false
                    for _, ng in ipairs(novel.genres) do
                        if ng == g then found = true; break end
                    end
                    if not found then include = false; break end
                end
            end

            if include then
                local tagsExc = normalizeList(filters["tags_excluded"])
                for _, t in ipairs(tagsExc) do
                    for _, nt in ipairs(novel.tags) do
                        if nt == t then include = false; break end
                    end
                    if not include then break end
                end
            end

            if include then
                local tagsInc = normalizeList(filters["tags_included"])
                for _, t in ipairs(tagsInc) do
                    local found = false
                    for _, nt in ipairs(novel.tags) do
                        if nt == t then found = true; break end
                    end
                    if not found then include = false; break end
                end
            end

            if include then
                local tagsSearch = filters["tags_search"]
                if tagsSearch and tagsSearch ~= "" then
                    local terms = {}
                    for term in tostring(tagsSearch):gmatch("[^,]+") do
                        local slug = toSlug(term)
                        if slug ~= "" then table.insert(terms, slug) end
                    end
                    for _, term in ipairs(terms) do
                        local found = false
                        for _, nt in ipairs(novel.tags) do
                            if nt:find(term, 1, true) then found = true; break end
                        end
                        if not found then include = false; break end
                    end
                end
            end
        end

        if include then
            table.insert(filtered, novel)
        end
    end

    local sortKey = "reviewCount"
    if filters and filters["order"] then
        sortKey = filters["order"]
    end
    table.sort(filtered, function(a, b)
        return (a[sortKey] or 0) > (b[sortKey] or 0)
    end)

    return filtered
end

-- ── Catalog ─────────────────────────────────────────────────────────────────

function getCatalogList(index)
    local allNovels = getAllNovels()
    local sorted = filterAndSort(allNovels, nil)
    local items = {}
    for _, n in ipairs(paginate(sorted, index)) do
        table.insert(items, novelToItem(n))
    end
    return { items = items, hasNext = #sorted > LIB("catalog").nextIndex(index) * 20 }
end

function getCatalogSearch(index, query)
    local allNovels = getAllNovels()
    local queryLower = query:lower()
    local results = {}
    for _, novel in ipairs(allNovels) do
        if novel.name:lower():find(queryLower, 1, true) then
            table.insert(results, novel)
        end
    end
    local items = {}
    for _, n in ipairs(paginate(results, index)) do
        table.insert(items, novelToItem(n))
    end
    return { items = items, hasNext = #results > LIB("catalog").nextIndex(index) * 20 }
end

function getCatalogFiltered(index, filters)
    local allNovels = getAllNovels()
    local sorted = filterAndSort(allNovels, filters)
    local items = {}
    for _, n in ipairs(paginate(sorted, index)) do
        table.insert(items, novelToItem(n))
    end
    return { items = items, hasNext = #sorted > LIB("catalog").nextIndex(index) * 20 }
end

-- ── Filters ─────────────────────────────────────────────────────────────────

local _filterListCache = nil

local POPULAR_TAGS_LIMIT = 40

local function slugToLabel(slug)
    local words = {}
    for w in slug:gmatch("[^%-]+") do
        table.insert(words, w:sub(1, 1):upper() .. w:sub(2))
    end
    return table.concat(words, " ")
end

-- Строим список самых часто встречающихся тегов по факту в загруженном каталоге
-- (а не наугад/по алфавиту, как было раньше со статичным списком из 800+ штук).
local function buildPopularTagOptions()
    local novels = getAllNovels()
    if not novels or #novels == 0 then return {} end

    local freq = {}
    for _, n in ipairs(novels) do
        for _, t in ipairs(n.tags) do
            freq[t] = (freq[t] or 0) + 1
        end
    end

    local list = {}
    for slug, count in pairs(freq) do
        table.insert(list, { slug = slug, count = count })
    end
    table.sort(list, function(a, b)
        if a.count ~= b.count then return a.count > b.count end
        return a.slug < b.slug
    end)

    local options = {}
    for i = 1, math.min(POPULAR_TAGS_LIMIT, #list) do
        table.insert(options, { value = list[i].slug, label = slugToLabel(list[i].slug) })
    end
    return options
end

